    "C23", "C24", "C28", "C29", "C32", "C33"
  ],
  "claims": [
    {
      "claim": "Mannitol, a highly polar sugar alcohol, has human absolute oral bioavailability of 0.228 at 150 g and about 20% at 100 g (C01, C06, C09, C17); L3 exposure records show dose-linear Cmax and AUC after 50–150 g oral mannitol (C35–C38, C40–C43, C45–C46), consistent with meaningful oral absorption.",
      "card_ids": ["C01", "C06", "C09", "C17", "C35", "C36", "C37", "C38", "C40", "C41", "C42", "C43", "C45", "C46"]
    },
    {
      "claim": "Glucose, another small polar sugar, had oral bioavailability estimates of 0.722 in healthy subjects (C16), 0.843 in type 1 diabetic patients (C10), and 38% in hypoglycemic children (C15), all at or above the 20% threshold.",
      "card_ids": ["C10", "C15", "C16"]
    },
    {
      "claim": "Sorbitol and propylene glycol, small polyols, showed oral bioavailability of 0.36–0.38 in shunted patients (C03, C19) and very high/close-to-complete in adults (C13, C28, C29), supporting that small polar polyhydroxy compounds can meet F ≥ 20%.",
      "card_ids": ["C03", "C19", "C13", "C28", "C29"]
    },
    {
      "claim": "Gemcitabine's low oral bioavailability (10%, range 5–17%; rat solution 9.86%) is attributed to first-pass metabolism by cytidine deaminase and high first-pass clearance (C07, C18, C20, C21, C26, C30), a mechanism not applicable to ascorbic acid; these low outcomes do not transfer.",
      "card_ids": ["C07", "C18", "C20", "C21", "C26", "C30"]
    },
    {
      "claim": "L3 records for uridine (C39) and clavulanic acid (C44) show oral exposure in mice/dogs but provide no absolute F or threshold-relevant comparison for ascorbic acid.",
      "card_ids": ["C39", "C44"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C35", "C36", "C37", "C38", "C40", "C41", "C42", "C43", "C45", "C46"]
    },
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C39", "C44"]
    }
  ],
  "evidence_gaps": [
    "No direct ascorbic acid oral bioavailability or matched oral/IV AUC record is present in the supplied cards.",
    "L3 mannitol exposure records lack an IV comparator in these cards, so they do not independently establish absolute F.",
    "Active transport (e.g., SVCT1/2) contribution to ascorbic acid absorption is inferred from the query prior caveat, not from a measured record.",
    "Dose dependence and saturation of ascorbic acid absorption are not captured.",
    "Transfer from mannitol/glucose/sorbitol/propylene glycol contexts is qualitative; species, patient status, and doses differ."
  ],
  "decision_summary": "Predicted high (F ≥ 20%): L3 oral exposure records for mannitol show dose-linear Cmax/AUC and reinforce that small polar polyhydroxy compounds are orally absorbed; combined with glucose, sorbitol, and propylene glycol F estimates at or above 20%, and no affirmative threshold-relevant low evidence for ascorbic acid, the high prediction is maintained with strengthened support."
}

